import http from 'node:http';

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ service: '{{SERVICE_NAME}}', status: 'healthy' }));
});

server.listen({{PORT}}, () => console.log('{{SERVICE_NAME}} listening on {{PORT}}'));
